export const GUIDE_HTML = "<!doctype html><html lang=\"fr\"><head><meta charset=utf8><meta name=viewport content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><style>:root{color-scheme:light;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}html{scroll-padding-top:env(safe-area-inset-top,0px)}body{margin:0;padding:0;font:14px -apple-system,BlinkMacSystemFont,sans-serif;background:#fff;color:#000}img{max-width:100%}[hidden]:not([hidden=until-found i]){display:none!important}</style></head><body>\n<title>Guide prospecteur Astrinova</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,500;12..96,600;12..96,700&family=Onest:wght@400;500;600&display=swap\">\n<style>\n/* Mise en page : sommaire collant à gauche (ordinateur), contenu en colonne de lecture ; sur téléphone, sommaire en bandeau défilant. */\n:root{\n  --bg:#F6F5FA; --surface:#FFFFFF; --surface-2:#EFEDF7; --ink:#17151F; --muted:#5D5A6B; --line:#E1DEEC;\n  --accent:#5B48C2; --accent-soft:#E9E5FA; --gold:#8F6420; --gold-soft:#F6ECD8; --ok:#1F7A55; --ok-soft:#E1F3EA; --warn:#A0442F; --warn-soft:#F8E6E1;\n  --display:'Bricolage Grotesque', 'Avenir Next', system-ui, sans-serif;\n  --body:'Onest', -apple-system, 'Segoe UI', system-ui, sans-serif;\n  --mono:ui-monospace, 'SF Mono', Menlo, Consolas, monospace;\n}\n@media (prefers-color-scheme: dark){\n  :root:not([data-theme=\"light\"]){\n    --bg:#0B0B10; --surface:#14141C; --surface-2:#1B1A25; --ink:#EEEDF4; --muted:#A3A0B3; --line:#2A2836;\n    --accent:#A99BEA; --accent-soft:#25213D; --gold:#E8C177; --gold-soft:#2E2617; --ok:#6FD3A6; --ok-soft:#14291F; --warn:#F0A08F; --warn-soft:#2E1A16;\n    color-scheme:dark;\n  }\n}\n:root[data-theme=\"dark\"]{\n  --bg:#0B0B10; --surface:#14141C; --surface-2:#1B1A25; --ink:#EEEDF4; --muted:#A3A0B3; --line:#2A2836;\n  --accent:#A99BEA; --accent-soft:#25213D; --gold:#E8C177; --gold-soft:#2E2617; --ok:#6FD3A6; --ok-soft:#14291F; --warn:#F0A08F; --warn-soft:#2E1A16;\n  color-scheme:dark;\n}\n*{box-sizing:border-box;}\nhtml{scroll-behavior:smooth;}\n@media (prefers-reduced-motion:reduce){ html{scroll-behavior:auto;} }\nbody{background:var(--bg);color:var(--ink);font-family:var(--body);font-size:16px;line-height:1.6;padding-inline:16px;}\na{color:var(--accent);text-underline-offset:2px;}\na:focus-visible,button:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:6px;}\n.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;}\n.page{max-width:1180px;margin:0 auto;display:grid;grid-template-columns:minmax(0,1fr);gap:40px;padding-block:32px 80px;}\n@media (min-width:1000px){ .page{grid-template-columns:230px minmax(0,1fr);gap:56px;} }\n\n/* sommaire */\n.toc{position:sticky;top:env(safe-area-inset-top,0px);z-index:5;background:var(--bg);margin-inline:-16px;padding:10px 16px;border-bottom:1px solid var(--line);}\n.toc-title{display:none;}\n.toc ol{list-style:none;margin:0;padding:0;display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;}\n.toc ol::-webkit-scrollbar{display:none;}\n.toc a{display:inline-flex;align-items:center;min-height:36px;padding:4px 12px;border-radius:999px;background:var(--surface);border:1px solid var(--line);color:var(--ink);text-decoration:none;font-size:14px;white-space:nowrap;}\n.toc a.is-here{background:var(--accent-soft);border-color:var(--accent);color:var(--accent);font-weight:600;}\n@media (min-width:1000px){\n  .toc{align-self:start;top:24px;margin:0;padding:0;border:none;background:none;}\n  .toc-title{display:block;font-family:var(--display);font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin:0 0 10px;}\n  .toc ol{flex-direction:column;gap:2px;overflow:visible;}\n  .toc a{background:none;border:none;border-radius:8px;padding:6px 10px;min-height:0;white-space:normal;color:var(--muted);}\n  .toc a:hover{color:var(--ink);background:var(--surface-2);}\n  .toc a.is-here{background:var(--accent-soft);}\n}\n\n/* contenu */\nmain{min-width:0;}\n.doc-head{margin-bottom:28px;}\n.eyebrow{font-family:var(--display);font-size:13px;letter-spacing:.1em;text-transform:uppercase;color:var(--accent);margin:0 0 10px;}\nh1{font-family:var(--display);font-weight:700;font-size:clamp(34px,5vw,52px);line-height:1.05;letter-spacing:-.015em;margin:0 0 14px;text-wrap:balance;}\n.lead{font-size:18px;color:var(--muted);max-width:62ch;margin:0;}\n.meta{font-size:14px;color:var(--muted);margin:14px 0 0;}\n.facts{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(200px,100%),1fr));gap:12px;margin:28px 0 8px;}\n.fact{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:14px 16px;min-width:0;}\n.fact span{display:block;font-size:13px;color:var(--muted);}\n.fact strong{display:block;font-family:var(--display);font-size:19px;line-height:1.25;margin-top:2px;}\nsection{padding-block:40px;border-top:1px solid var(--line);scroll-margin-top:64px;}\n@media (min-width:1000px){ section{scroll-margin-top:16px;} }\nh2{font-family:var(--display);font-weight:600;font-size:clamp(25px,3vw,32px);line-height:1.15;letter-spacing:-.01em;margin:0 0 8px;text-wrap:balance;}\n.section-intro{color:var(--muted);max-width:66ch;margin:0 0 22px;}\nh3{font-family:var(--display);font-weight:600;font-size:20px;line-height:1.25;margin:28px 0 10px;}\np{max-width:68ch;margin:0 0 12px;}\nul.plain{margin:0 0 12px;padding-left:20px;display:flex;flex-direction:column;gap:6px;max-width:68ch;}\nstrong{font-weight:600;}\n.nb{font-variant-numeric:tabular-nums;white-space:nowrap;}\n\n/* encadrés */\n.note{border-radius:12px;padding:14px 16px;margin:16px 0;max-width:72ch;}\n.note p:last-child{margin-bottom:0;}\n.note-title{display:block;font-weight:600;margin-bottom:4px;}\n.note.info{background:var(--accent-soft);}\n.note.warn{background:var(--warn-soft);}\n.note.warn .note-title{color:var(--warn);}\n\n/* packs */\n.packs{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(260px,100%),1fr));gap:14px;}\n.pack{background:var(--surface);border:1px solid var(--line);border-radius:16px;padding:20px;display:flex;flex-direction:column;gap:10px;min-width:0;}\n.pack.signature{border-color:var(--gold);}\n.pack-top{display:flex;align-items:baseline;justify-content:space-between;gap:10px;flex-wrap:wrap;}\n.pack-name{font-family:var(--display);font-size:22px;font-weight:600;}\n.pack-price{font-family:var(--display);font-size:28px;font-weight:700;font-variant-numeric:tabular-nums;}\n.pack.signature .pack-price{color:var(--gold);}\n.pack-tag{font-size:14px;color:var(--muted);margin:0;}\n.pack ul{margin:0;padding-left:18px;display:flex;flex-direction:column;gap:4px;font-size:15px;}\n.pack-foot{margin-top:auto;padding-top:10px;border-top:1px solid var(--line);font-size:14px;color:var(--muted);display:flex;flex-direction:column;gap:2px;}\n.pack-foot b{color:var(--ink);font-weight:600;}\n\n/* tableaux */\n.table-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:14px;background:var(--surface);margin:8px 0 12px;}\ntable{width:100%;border-collapse:collapse;font-size:15px;min-width:640px;}\nth{text-align:left;font-family:var(--display);font-weight:600;font-size:13px;letter-spacing:.04em;text-transform:uppercase;color:var(--muted);padding:12px 14px;border-bottom:1px solid var(--line);background:var(--surface-2);}\ntd{padding:12px 14px;border-bottom:1px solid var(--line);vertical-align:top;}\ntr:last-child td{border-bottom:none;}\ntd.prix{font-variant-numeric:tabular-nums;white-space:nowrap;font-weight:600;}\n.cat-row td{background:var(--surface-2);font-family:var(--display);font-weight:600;font-size:14px;letter-spacing:.03em;}\n.chip{display:inline-block;font-size:12px;font-weight:600;padding:2px 8px;border-radius:999px;margin:2px 4px 2px 0;white-space:nowrap;}\n.chip.pop{background:var(--accent-soft);color:var(--accent);}\n.chip.reco,.chip.sig{background:var(--gold-soft);color:var(--gold);}\n\n/* exemples de calcul */\n.calcs{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(250px,100%),1fr));gap:14px;}\n.calc{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px 18px;min-width:0;}\n.calc h3{margin:0 0 8px;font-size:18px;}\n.calc dl{margin:0;display:grid;grid-template-columns:1fr auto;gap:4px 12px;font-size:15px;}\n.calc dt{color:var(--muted);}\n.calc dd{margin:0;text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap;}\n.calc .total{border-top:1px solid var(--line);padding-top:6px;margin-top:4px;color:var(--ink);font-weight:600;}\n\n/* réalisations */\n.works{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(250px,100%),1fr));gap:12px;}\n.work{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px;display:flex;flex-direction:column;gap:6px;min-width:0;}\n.work-pack{font-size:12px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);}\n.work-name{font-family:var(--display);font-size:19px;font-weight:600;}\n.work p{font-size:15px;color:var(--muted);margin:0;}\n.work a{font-size:15px;overflow-wrap:anywhere;}\n\n/* étapes */\n.steps{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;counter-reset:step;}\n.steps li{display:grid;grid-template-columns:40px minmax(0,1fr);gap:14px;padding:14px 0;border-bottom:1px solid var(--line);}\n.steps li:last-child{border-bottom:none;}\n.steps li::before{counter-increment:step;content:counter(step);width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:var(--accent-soft);color:var(--accent);font-family:var(--display);font-weight:700;}\n.steps b{display:block;}\n.steps span{color:var(--muted);}\n\n/* modèles de messages */\n.template{background:var(--surface);border:1px solid var(--line);border-radius:14px;margin:12px 0 18px;overflow:hidden;}\n.template-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 14px;border-bottom:1px solid var(--line);background:var(--surface-2);flex-wrap:wrap;}\n.template-head b{font-size:15px;}\n.template-body{padding:14px 16px;white-space:pre-line;font-size:15px;max-width:72ch;overflow-wrap:anywhere;}\n.var{background:var(--accent-soft);color:var(--accent);border-radius:4px;padding:0 4px;font-weight:500;}\nbutton.copy{font:inherit;font-size:14px;font-weight:600;min-height:36px;padding:4px 14px;border-radius:999px;border:1px solid var(--accent);background:var(--surface);color:var(--accent);cursor:pointer;flex:none;}\nbutton.copy:hover{background:var(--accent-soft);}\nbutton.copy.done{background:var(--ok-soft);border-color:var(--ok);color:var(--ok);}\n\n/* liens et contacts */\n.links{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(300px,100%),1fr));gap:10px;}\n.link{display:flex;align-items:center;justify-content:space-between;gap:12px;background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:12px 14px;min-width:0;}\n.link div{min-width:0;}\n.link b{display:block;font-size:15px;}\n.link a,.link code{font-size:14px;overflow-wrap:anywhere;}\n.link code{font-family:var(--mono);color:var(--ink);}\n\n/* FAQ */\ndetails{background:var(--surface);border:1px solid var(--line);border-radius:12px;margin:0 0 8px;max-width:78ch;}\nsummary{cursor:pointer;padding:14px 16px;font-weight:600;list-style:none;display:flex;justify-content:space-between;gap:12px;}\nsummary::-webkit-details-marker{display:none;}\nsummary::after{content:'+';color:var(--accent);font-family:var(--display);font-size:20px;line-height:1;}\ndetails[open] summary::after{content:'–';}\ndetails > div{padding:0 16px 14px;}\ndetails > div p:last-child{margin-bottom:0;}\n.faq-tools{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:0 0 14px;}\n.faq-tools input{flex:1 1 260px;font:inherit;font-size:16px;padding:10px 14px;border-radius:10px;border:1px solid var(--line);background:var(--surface);color:var(--ink);min-width:0;}\n.faq-tools input:focus{outline:2px solid var(--accent);outline-offset:1px;}\n.faq-count{font-size:14px;color:var(--muted);}\n\n/* règles */\n.rules{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(300px,100%),1fr));gap:14px;}\n.rule-col{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px 18px;}\n.rule-col h3{margin-top:0;}\n.rule-col.do h3{color:var(--ok);}\n.rule-col.dont h3{color:var(--warn);}\n.rule-col ul{margin:0;padding-left:18px;display:flex;flex-direction:column;gap:6px;}\n\ndl.glossary{display:grid;grid-template-columns:minmax(0,1fr);margin:0;max-width:78ch;}\ndl.glossary div{padding:12px 0;border-bottom:1px solid var(--line);}\ndl.glossary dt{font-weight:600;}\ndl.glossary dd{margin:2px 0 0;color:var(--muted);}\nfooter.end{color:var(--muted);font-size:14px;padding-top:24px;border-top:1px solid var(--line);}\n</style>\n\n<div class=\"page\">\n  <nav class=\"toc\" aria-label=\"Sommaire\">\n    <p class=\"toc-title\">Sommaire</p>\n    <ol>\n      <li><a href=\"#role\">Votre rôle</a></li>\n      <li><a href=\"#essentiel\">L’essentiel</a></li>\n      <li><a href=\"#liens\">Liens et contacts</a></li>\n      <li><a href=\"#packs\">Les packs</a></li>\n      <li><a href=\"#abonnement\">L’abonnement</a></li>\n      <li><a href=\"#options\">Les options</a></li>\n      <li><a href=\"#exemples\">Exemples de devis</a></li>\n      <li><a href=\"#realisations\">Réalisations</a></li>\n      <li><a href=\"#parcours\">Parcours client</a></li>\n      <li><a href=\"#messages\">Modèles de messages</a></li>\n      <li><a href=\"#faq\">Questions fréquentes</a></li>\n      <li><a href=\"#objections\">Objections</a></li>\n      <li><a href=\"#regles\">Règles d’or</a></li>\n      <li><a href=\"#transmettre\">Transmettre un prospect</a></li>\n      <li><a href=\"#lexique\">Lexique</a></li>\n    </ol>\n  </nav>\n\n  <main>\n    <header class=\"doc-head\">\n      <p class=\"eyebrow\">Astrinova · Équipe prospection</p>\n      <h1>Guide du prospecteur</h1>\n      <p class=\"lead\">Tout ce qu’il faut savoir pour présenter Astrinova, répondre aux questions des commerçants et leur faire découvrir nos offres, sans jamais promettre ce qu’on ne fait pas.</p>\n      <p class=\"meta\">Mis à jour le 13 octobre 2026. En cas de doute sur un prix, la <a href=\"https://getnovaai.vercel.app/tarifs.html\" target=\"_blank\" rel=\"noopener\">page Tarifs du site</a> fait toujours foi.</p>\n      <div class=\"facts\">\n        <div class=\"fact\"><span>Ce qu’on vend</span><strong>Des sites internet pour commerces</strong></div>\n        <div class=\"fact\"><span>Prix des packs</span><strong class=\"nb\">290 € à 990 €</strong></div>\n        <div class=\"fact\"><span>Paiement du site</span><strong>Une seule fois</strong></div>\n        <div class=\"fact\"><span>Délai de création</span><strong>1 semaine à 1 mois</strong></div>\n      </div>\n    </header>\n\n    <section id=\"role\">\n      <h2>Votre rôle</h2>\n      <p class=\"section-intro\">Simple et clair : vous trouvez les clients, l’équipe fait le reste.</p>\n      <ol class=\"steps\">\n        <li><div><b>Trouver des clients potentiels</b><span>C’est votre mission principale : repérer les commerces qui ont besoin d’un site (pas de site, site daté, pas de réservation ou de commande en ligne…).</span></div></li>\n        <li><div><b>Commencer la conversation, si vous le souhaitez</b><span>Ce n’est pas obligatoire. Si vous le faites, utilisez les <a href=\"#messages\">modèles de messages</a> de ce guide.</span></div></li>\n        <li><div><b>Prévenir l’équipe dès qu’un client est intéressé</b><span>Par e-mail à <strong>astrinova.website@gmail.com</strong>, avec la <a href=\"#transmettre\">fiche de transmission</a>. N’attendez pas : un client intéressé doit avoir une réponse rapidement.</span></div></li>\n        <li><div><b>Lui envoyer deux liens</b><span>La page Tarifs (<a href=\"https://getnovaai.vercel.app/tarifs.html\" target=\"_blank\" rel=\"noopener\">getnovaai.vercel.app/tarifs.html</a>) et le formulaire de maquette (<a href=\"https://astrinovaformulaire.netlify.app/\" target=\"_blank\" rel=\"noopener\">astrinovaformulaire.netlify.app</a>). Le modèle « Client intéressé » les contient déjà.</span></div></li>\n      </ol>\n      <div class=\"note info\">\n        <span class=\"note-title\">Ce que vous ne gérez pas</span>\n        <p>Le devis, les prix spéciaux, la maquette, le paiement et la mise en ligne sont gérés par l’équipe. Pour toute question : <strong>astrinova.website@gmail.com</strong>.</p>\n      </div>\n    </section>\n\n    <section id=\"essentiel\">\n      <h2>L’essentiel en une minute</h2>\n      <p class=\"section-intro\">À retenir avant votre premier message.</p>\n      <p><strong>Astrinova</strong> conçoit des sites internet professionnels pour les commerces et les petites entreprises&nbsp;: restaurants, snacks, salons de thé, bubble tea, cafés, boulangeries, coiffeurs, barbiers, instituts de beauté, boutiques…</p>\n      <p>Notre promesse, telle qu’elle est écrite sur le site&nbsp;: un site clair, rapide, pensé pour donner confiance, <strong>sans jargon technique et sans mauvaise surprise sur le prix</strong>.</p>\n      <h3>Ce qui nous distingue</h3>\n      <ul class=\"plain\">\n        <li><strong>Des prix affichés publiquement.</strong> Le commerçant compose lui-même son site sur la page Tarifs et voit le total exact, sans laisser ses coordonnées.</li>\n        <li><strong>Le site se paie une seule fois.</strong> Pas de contrat de location sur plusieurs années.</li>\n        <li><strong>Un abonnement facultatif</strong> (hébergement, nom de domaine, sécurité, mises à jour et actualités), résiliable à tout moment.</li>\n        <li><strong>Une maquette avant tout.</strong> Le client voit son site avant la mise en ligne et peut demander des ajustements. Rien n’est publié sans son accord.</li>\n        <li><strong>Des délais maximum annoncés</strong>&nbsp;: 1 semaine (Essentiel), 2 semaines (Pro), 1 mois (Signature).</li>\n        <li><strong>Une réponse sous 24&nbsp;h</strong> à chaque demande.</li>\n      </ul>\n      <div class=\"note info\">\n        <span class=\"note-title\">À retenir</span>\n        <p>Dès qu’un commerçant est intéressé&nbsp;: prévenez l’équipe à astrinova.website@gmail.com, puis envoyez-lui la page Tarifs et le formulaire de maquette. L’équipe prend le relais pour le devis, la maquette et la mise en ligne.</p>\n      </div>\n    </section>\n\n    <section id=\"liens\">\n      <h2>Liens et contacts</h2>\n      <p class=\"section-intro\">À garder sous la main. Le bouton «&nbsp;Copier&nbsp;» met le lien dans votre presse-papiers.</p>\n      <h3>Les liens à envoyer et les pages du site</h3>\n      <div class=\"links\">\n        <div class=\"link\"><div><b>Tarifs et panier (le plus important)</b><a href=\"https://getnovaai.vercel.app/tarifs.html\" target=\"_blank\" rel=\"noopener\">getnovaai.vercel.app/tarifs.html</a></div><button class=\"copy\" type=\"button\" data-copy=\"https://getnovaai.vercel.app/tarifs.html\">Copier</button></div>\n        <div class=\"link\"><div><b>Formulaire de maquette (à envoyer au client)</b><a href=\"https://astrinovaformulaire.netlify.app/\" target=\"_blank\" rel=\"noopener\">astrinovaformulaire.netlify.app</a></div><button class=\"copy\" type=\"button\" data-copy=\"https://astrinovaformulaire.netlify.app/\">Copier</button></div>\n        <div class=\"link\"><div><b>Réalisations par pack</b><a href=\"https://getnovaai.vercel.app/deja-en-ligne.html\" target=\"_blank\" rel=\"noopener\">getnovaai.vercel.app/deja-en-ligne.html</a></div><button class=\"copy\" type=\"button\" data-copy=\"https://getnovaai.vercel.app/deja-en-ligne.html\">Copier</button></div>\n        <div class=\"link\"><div><b>Accueil</b><a href=\"https://getnovaai.vercel.app/commerce.html\" target=\"_blank\" rel=\"noopener\">getnovaai.vercel.app/commerce.html</a></div><button class=\"copy\" type=\"button\" data-copy=\"https://getnovaai.vercel.app/commerce.html\">Copier</button></div>\n        <div class=\"link\"><div><b>Comment ça marche</b><a href=\"https://getnovaai.vercel.app/comment-ca-marche.html\" target=\"_blank\" rel=\"noopener\">getnovaai.vercel.app/comment-ca-marche.html</a></div><button class=\"copy\" type=\"button\" data-copy=\"https://getnovaai.vercel.app/comment-ca-marche.html\">Copier</button></div>\n        <div class=\"link\"><div><b>Ce que vous recevez</b><a href=\"https://getnovaai.vercel.app/ce-que-vous-recevez.html\" target=\"_blank\" rel=\"noopener\">getnovaai.vercel.app/ce-que-vous-recevez.html</a></div><button class=\"copy\" type=\"button\" data-copy=\"https://getnovaai.vercel.app/ce-que-vous-recevez.html\">Copier</button></div>\n        <div class=\"link\"><div><b>Contact</b><a href=\"https://getnovaai.vercel.app/contact.html\" target=\"_blank\" rel=\"noopener\">getnovaai.vercel.app/contact.html</a></div><button class=\"copy\" type=\"button\" data-copy=\"https://getnovaai.vercel.app/contact.html\">Copier</button></div>\n        <div class=\"link\"><div><b>Mentions légales</b><a href=\"https://getnovaai.vercel.app/mentions-legales.html\" target=\"_blank\" rel=\"noopener\">getnovaai.vercel.app/mentions-legales.html</a></div><button class=\"copy\" type=\"button\" data-copy=\"https://getnovaai.vercel.app/mentions-legales.html\">Copier</button></div>\n        <div class=\"link\"><div><b>Confidentialité</b><a href=\"https://getnovaai.vercel.app/confidentialite.html\" target=\"_blank\" rel=\"noopener\">getnovaai.vercel.app/confidentialite.html</a></div><button class=\"copy\" type=\"button\" data-copy=\"https://getnovaai.vercel.app/confidentialite.html\">Copier</button></div>\n      </div>\n      <h3>Contacter l’équipe</h3>\n      <div class=\"links\">\n        <div class=\"link\"><div><b>E-mail de l’équipe (questions, clients potentiels, tout)</b><code>astrinova.website@gmail.com</code></div><button class=\"copy\" type=\"button\" data-copy=\"astrinova.website@gmail.com\">Copier</button></div>\n        <div class=\"link\"><div><b>Téléphone</b><code>06 22 82 88 32</code></div><button class=\"copy\" type=\"button\" data-copy=\"06 22 82 88 32\">Copier</button></div>\n        <div class=\"link\"><div><b>Téléphone</b><code>06 52 23 75 73</code></div><button class=\"copy\" type=\"button\" data-copy=\"06 52 23 75 73\">Copier</button></div>\n      </div>\n      <p>Les demandes envoyées depuis le site et les réponses au formulaire de maquette arrivent automatiquement à l’équipe.</p>\n    </section>\n\n    <section id=\"packs\">\n      <h2>Les trois packs</h2>\n      <p class=\"section-intro\">Le pack, c’est la base du site. Il se paie une seule fois. Le contenu ci-dessous est celui affiché sur la page Tarifs.</p>\n      <div class=\"packs\">\n        <article class=\"pack\">\n          <div class=\"pack-top\"><span class=\"pack-name\">Essentiel</span><span class=\"pack-price\">290&nbsp;€</span></div>\n          <p class=\"pack-tag\">Un site simple, efficace, qui fait le travail.</p>\n          <ul>\n            <li>Site simple, sur-mesure</li>\n            <li>Optimisé mobile</li>\n            <li>Première maquette personnalisée</li>\n            <li>Mise en ligne rapide</li>\n          </ul>\n          <div class=\"pack-foot\"><span><b>Délai&nbsp;:</b> 1 semaine maximum</span><span><b>Abonnement&nbsp;:</b> 25&nbsp;€ par mois (facultatif)</span></div>\n        </article>\n        <article class=\"pack\">\n          <div class=\"pack-top\"><span class=\"pack-name\">Pro</span><span class=\"pack-price\">490&nbsp;€</span></div>\n          <p class=\"pack-tag\">Un site professionnel pensé pour votre commerce.</p>\n          <ul>\n            <li>Tout ce qui est inclus dans Essentiel</li>\n            <li>Site professionnel de commerce</li>\n            <li>Présentation des nouveautés et des offres</li>\n            <li>Mise en avant des avis clients</li>\n          </ul>\n          <div class=\"pack-foot\"><span><b>Délai&nbsp;:</b> 2 semaines maximum</span><span><b>Abonnement&nbsp;:</b> 25&nbsp;€ par mois (facultatif)</span></div>\n        </article>\n        <article class=\"pack signature\">\n          <div class=\"pack-top\"><span class=\"pack-name\">Signature</span><span class=\"pack-price\">990&nbsp;€</span></div>\n          <p class=\"pack-tag\">Une expérience web haut de gamme, en 3D.</p>\n          <ul>\n            <li>Tout ce qui est inclus dans Pro</li>\n            <li>Site en 3D avec animations</li>\n            <li>Fonctionnalités avancées sur mesure</li>\n            <li>Commande <em>ou</em> réservation en ligne incluse (au choix)</li>\n            <li>Abonnement réduit à 15&nbsp;€ par mois</li>\n            <li>Accompagnement prioritaire</li>\n          </ul>\n          <div class=\"pack-foot\"><span><b>Délai&nbsp;:</b> 1 mois maximum</span><span><b>Abonnement&nbsp;:</b> 15&nbsp;€ par mois (facultatif)</span></div>\n        </article>\n      </div>\n      <h3>Quel pack proposer&nbsp;?</h3>\n      <div class=\"table-wrap\">\n        <table>\n          <thead><tr><th>Le commerçant…</th><th>Pack à proposer</th><th>Pourquoi</th></tr></thead>\n          <tbody>\n            <tr><td>n’a pas de site et veut surtout exister en ligne (adresse, horaires, contact)</td><td><strong>Essentiel</strong></td><td>Le moins cher, en ligne en une semaine maximum.</td></tr>\n            <tr><td>veut présenter ses produits, ses nouveautés, ses offres et ses avis clients</td><td><strong>Pro</strong></td><td>Conçu pour les commerces ; le meilleur équilibre prix / contenu.</td></tr>\n            <tr><td>veut vendre ou prendre des rendez-vous en ligne</td><td><strong>Pro</strong> + option, ou <strong>Signature</strong></td><td>Signature inclut la commande <em>ou</em> la réservation en ligne : à comparer avec Pro + l’option.</td></tr>\n            <tr><td>veut se démarquer avec un site spectaculaire (3D, animations)</td><td><strong>Signature</strong></td><td>Le haut de gamme, avec l’abonnement le moins cher.</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"note info\">\n        <span class=\"note-title\">Astuce de calcul</span>\n        <p>Pour un commerce qui veut la commande en ligne&nbsp;: Pro + option commande = <span class=\"nb\">490 + 290 = 780 €</span> (à partir de), contre <span class=\"nb\">990 €</span> pour Signature, qui l’inclut et ajoute la 3D, l’accompagnement prioritaire et l’abonnement à 15&nbsp;€ au lieu de 25&nbsp;€.</p>\n      </div>\n    </section>\n\n    <section id=\"abonnement\">\n      <h2>L’abonnement</h2>\n      <p class=\"section-intro\">Facultatif et résiliable à tout moment. C’est nous qui gardons le site en ligne, sécurisé et à jour.</p>\n      <div class=\"table-wrap\">\n        <table>\n          <thead><tr><th>Avec le pack</th><th>Prix par mois</th><th>Ce qui est compris</th></tr></thead>\n          <tbody>\n            <tr><td>Essentiel ou Pro</td><td class=\"prix\">25&nbsp;€</td><td rowspan=\"2\">Hébergement · Nom de domaine · Sécurité · Mises à jour et ajout des actualités (nouvelle boisson de saison, nouvelles offres…)</td></tr>\n            <tr><td>Signature</td><td class=\"prix\">15&nbsp;€</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <p><strong>L’argument à retenir&nbsp;:</strong> le commerçant n’a rien de technique à gérer. Une nouvelle carte, une offre du moment, un changement d’horaires&nbsp;? Il nous l’envoie et nous l’ajoutons pour lui.</p>\n    </section>\n\n    <section id=\"options\">\n      <h2>Les options à la carte</h2>\n      <p class=\"section-intro\">Le commerçant ajoute uniquement ce dont il a besoin. Les prix «&nbsp;à partir de&nbsp;» sont confirmés par l’équipe dans le devis.</p>\n      <div class=\"table-wrap\">\n        <table>\n          <thead><tr><th>Option</th><th>Prix</th><th>Ce que c’est</th><th>Idéal pour</th></tr></thead>\n          <tbody>\n            <tr class=\"cat-row\"><td colspan=\"4\">Vendre et réserver</td></tr>\n            <tr><td><strong>Commande en ligne (click &amp; collect)</strong><br><span class=\"chip pop\">Populaire</span><span class=\"chip sig\">Incluse avec Signature</span></td><td class=\"prix\">dès 290&nbsp;€</td><td>Les clients commandent et paient sur le site, puis viennent récupérer leur commande. Sans les commissions des plateformes de livraison.</td><td>Restaurants, snacks, boulangeries, salons de thé</td></tr>\n            <tr><td><strong>Réservation en ligne</strong><br><span class=\"chip pop\">Populaire</span><span class=\"chip sig\">Incluse avec Signature</span></td><td class=\"prix\">dès 120&nbsp;€</td><td>Réserver une table ou prendre rendez-vous depuis le site, 24&nbsp;h/24.</td><td>Restaurants, coiffeurs, barbiers, instituts de beauté</td></tr>\n            <tr><td><strong>Bons cadeaux en ligne</strong></td><td class=\"prix\">dès 150&nbsp;€</td><td>Cartes cadeaux achetées en quelques clics et reçues par e-mail. Idéal pour les fêtes et les anniversaires.</td><td>Instituts de beauté, coiffeurs, restaurants, salons de thé</td></tr>\n            <tr class=\"cat-row\"><td colspan=\"4\">Être trouvé et inspirer confiance</td></tr>\n            <tr><td><strong>Fiche Google optimisée et QR code d’avis</strong><br><span class=\"chip reco\">Recommandé</span></td><td class=\"prix\">75&nbsp;€</td><td>Création ou optimisation de la fiche Google Maps (photos, horaires, catégories, description), avec un QR code à poser en caisse pour récolter plus d’avis.</td><td>Tous les commerces</td></tr>\n            <tr><td><strong>Adresse mail professionnelle</strong></td><td class=\"prix\">40&nbsp;€</td><td>Une adresse à son nom (contact@moncommerce.fr) au lieu d’une adresse Gmail ou Hotmail. Le nom de domaine, lui, est compris dans l’abonnement.</td><td>Tous les commerces</td></tr>\n            <tr><td><strong>Version anglaise du site</strong></td><td class=\"prix\">100&nbsp;€</td><td>Tout le site traduit en anglais, avec un bouton pour changer de langue.</td><td>Restaurants, cafés, commerces en zone touristique</td></tr>\n            <tr class=\"cat-row\"><td colspan=\"4\">Image et visuel</td></tr>\n            <tr><td><strong>Création de logo simple</strong></td><td class=\"prix\">dès 90&nbsp;€</td><td>Un logo propre, livré dans tous les formats utiles : site, réseaux sociaux, enseigne, impression.</td><td>Commerces sans logo ou qui veulent le moderniser</td></tr>\n            <tr><td><strong>Galerie avant / après</strong></td><td class=\"prix\">50&nbsp;€</td><td>Un curseur interactif pour comparer avant et après.</td><td>Coiffeurs, barbiers, instituts de beauté</td></tr>\n            <tr><td><strong>Carte interactive avec QR code</strong></td><td class=\"prix\">70&nbsp;€</td><td>Une photo par produit, des catégories claires, des prix faciles à mettre à jour, et un QR code sur les tables qui mène à la carte.</td><td>Restaurants, snacks, salons de thé, bubble tea, cafés</td></tr>\n            <tr class=\"cat-row\"><td colspan=\"4\">Fidéliser</td></tr>\n            <tr><td><strong>Fil Instagram intégré</strong></td><td class=\"prix\">60&nbsp;€</td><td>Les dernières publications Instagram s’affichent automatiquement sur le site. Nécessite un compte Instagram professionnel (gratuit).</td><td>Salons de thé, bubble tea, boutiques, barbiers</td></tr>\n            <tr><td><strong>Carte de fidélité digitale</strong></td><td class=\"prix\">dès 250&nbsp;€</td><td>Une carte à tampons sur le téléphone des clients, qui reviennent plus souvent.</td><td>Salons de thé, cafés, boulangeries, barbiers, snacks</td></tr>\n            <tr class=\"cat-row\"><td colspan=\"4\">Sur mesure</td></tr>\n            <tr><td><strong>Fonctionnalité qui n’est pas dans la liste</strong></td><td class=\"prix\">Sur devis</td><td>Le client l’ajoute une seule fois, même pour plusieurs besoins : une fenêtre s’ouvre et il décrit tout ce qu’il souhaite. L’équipe répond avec un prix adapté.</td><td>Tous les besoins particuliers</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"note info\">\n        <span class=\"note-title\">La règle Signature</span>\n        <p>Avec Signature, <strong>une</strong> option entre commande et réservation en ligne est offerte. Si le client prend les deux, la plus chère (la commande en ligne) est offerte et l’autre est facturée. Le panier du site fait ce calcul tout seul.</p>\n      </div>\n    </section>\n\n    <section id=\"exemples\">\n      <h2>Exemples de devis</h2>\n      <p class=\"section-intro\">Pour donner un ordre d’idée au téléphone. Le client obtient le même calcul sur la page Tarifs. Ce sont des exemples de composition, pas des clients réels.</p>\n      <div class=\"calcs\">\n        <div class=\"calc\">\n          <h3>Un snack qui veut le click &amp; collect</h3>\n          <dl>\n            <dt>Pack Pro</dt><dd>490&nbsp;€</dd>\n            <dt>Commande en ligne</dt><dd>dès 290&nbsp;€</dd>\n            <dt>Fiche Google + QR code</dt><dd>75&nbsp;€</dd>\n            <dt class=\"total\">À payer une fois</dt><dd class=\"total\">dès 855&nbsp;€</dd>\n            <dt>Abonnement</dt><dd>25&nbsp;€ / mois</dd>\n          </dl>\n        </div>\n        <div class=\"calc\">\n          <h3>Un coiffeur qui veut des rendez-vous</h3>\n          <dl>\n            <dt>Pack Essentiel</dt><dd>290&nbsp;€</dd>\n            <dt>Réservation en ligne</dt><dd>dès 120&nbsp;€</dd>\n            <dt>Galerie avant / après</dt><dd>50&nbsp;€</dd>\n            <dt>Fiche Google + QR code</dt><dd>75&nbsp;€</dd>\n            <dt class=\"total\">À payer une fois</dt><dd class=\"total\">dès 535&nbsp;€</dd>\n            <dt>Abonnement</dt><dd>25&nbsp;€ / mois</dd>\n          </dl>\n        </div>\n        <div class=\"calc\">\n          <h3>Un bubble tea qui veut fidéliser</h3>\n          <dl>\n            <dt>Pack Pro</dt><dd>490&nbsp;€</dd>\n            <dt>Carte interactive + QR code</dt><dd>70&nbsp;€</dd>\n            <dt>Fil Instagram intégré</dt><dd>60&nbsp;€</dd>\n            <dt>Carte de fidélité</dt><dd>dès 250&nbsp;€</dd>\n            <dt class=\"total\">À payer une fois</dt><dd class=\"total\">dès 870&nbsp;€</dd>\n            <dt>Abonnement</dt><dd>25&nbsp;€ / mois</dd>\n          </dl>\n        </div>\n        <div class=\"calc\">\n          <h3>Un restaurant haut de gamme</h3>\n          <dl>\n            <dt>Pack Signature</dt><dd>990&nbsp;€</dd>\n            <dt>Réservation en ligne</dt><dd>incluse</dd>\n            <dt>Version anglaise</dt><dd>100&nbsp;€</dd>\n            <dt class=\"total\">À payer une fois</dt><dd class=\"total\">1&nbsp;090&nbsp;€</dd>\n            <dt>Abonnement</dt><dd>15&nbsp;€ / mois</dd>\n          </dl>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"realisations\">\n      <h2>Les réalisations à montrer</h2>\n      <p class=\"section-intro\">Ce sont les sites présentés sur la page «&nbsp;Déjà en ligne&nbsp;», classés par pack. Envoyez de préférence le lien de cette page, qui les regroupe.</p>\n      <div class=\"works\">\n        <div class=\"work\"><span class=\"work-pack\">Pack Essentiel</span><span class=\"work-name\">The Finals Moments</span><p>Site d’un créateur de contenu sur le jeu The Finals.</p><a href=\"https://site-l-u1lzdazd.vercel.app/\" target=\"_blank\" rel=\"noopener\">site-l-u1lzdazd.vercel.app</a></div>\n        <div class=\"work\"><span class=\"work-pack\">Pack Essentiel</span><span class=\"work-name\">DailyGameCheck</span><p>Site d’un créateur qui note un jeu vidéo chaque jour.</p><a href=\"https://site-l-dm8hpwxy.vercel.app/\" target=\"_blank\" rel=\"noopener\">site-l-dm8hpwxy.vercel.app</a></div>\n        <div class=\"work\"><span class=\"work-pack\">Pack Essentiel</span><span class=\"work-name\">Xsam</span><p>Media kit d’un créateur de contenu Fortnite.</p><a href=\"https://site-l-1dwb8rce.vercel.app/\" target=\"_blank\" rel=\"noopener\">site-l-1dwb8rce.vercel.app</a></div>\n        <div class=\"work\"><span class=\"work-pack\">Pack Pro</span><span class=\"work-name\">Astrinova</span><p>Application web qui réunit des marques de vêtements, avec le suivi des prix.</p><a href=\"https://www.astrinova.fr/\" target=\"_blank\" rel=\"noopener\">astrinova.fr</a></div>\n        <div class=\"work\"><span class=\"work-pack\">Pack Pro</span><span class=\"work-name\">Troc Livres</span><p>Plateforme où les élèves donnent ou revendent leurs livres au sein de leur établissement.</p><a href=\"https://troclivres.fr/\" target=\"_blank\" rel=\"noopener\">troclivres.fr</a></div>\n        <div class=\"work\"><span class=\"work-pack\">Pack Signature</span><span class=\"work-name\">L’UNIVEUW</span><p>Site sur-mesure d’un duo de rap, autour de leur album et de leurs singles.</p><a href=\"https://luniveuw.vercel.app/\" target=\"_blank\" rel=\"noopener\">luniveuw.vercel.app</a></div>\n      </div>\n      <div class=\"note warn\">\n        <span class=\"note-title\">Comment en parler honnêtement</span>\n        <p>Présentez-les comme des sites réalisés par l’équipe. N’inventez ni témoignage, ni chiffre de résultats, ni nom de client. Les sites Essentiel sont des sites de créateurs de contenu : montrez-les pour la qualité du rendu, pas comme des exemples de commerces.</p>\n      </div>\n    </section>\n\n    <section id=\"parcours\">\n      <h2>Le parcours d’un client</h2>\n      <p class=\"section-intro\">De votre premier message à la mise en ligne.</p>\n      <ol class=\"steps\">\n        <li><div><b>Vous trouvez le client</b><span>Et, si vous le souhaitez, vous commencez la conversation (Instagram, e-mail, téléphone ou en boutique).</span></div></li>\n        <li><div><b>Vous prévenez l’équipe</b><span>Dès qu’il est intéressé, par e-mail à astrinova.website@gmail.com, avec la fiche de transmission.</span></div></li>\n        <li><div><b>Vous lui envoyez les tarifs et le formulaire</b><span>Sur la page Tarifs, il compose son site et voit le total ; il peut aussi cliquer sur « Envoyer ma demande ». Le formulaire « Votre maquette sur mesure » lui pose 8 questions sur ses goûts (ambiance, style, couleurs, logo, ce qu’il ne veut pas, inspirations, priorités, pages), en environ 4 minutes. Seuls le nom du commerce et un moyen de le joindre sont obligatoires, et ses réponses nous arrivent automatiquement.</span></div></li>\n        <li><div><b>L’équipe répond sous 24 h</b><span>Pour confirmer le projet et les prix « à partir de ».</span></div></li>\n        <li><div><b>La maquette</b><span>À partir de ses réponses au formulaire, l’équipe réalise une maquette à son image et lui envoie des captures.</span></div></li>\n        <li><div><b>Validation et mise en ligne</b><span>Il voit son site avant la mise en ligne et peut demander des ajustements. Rien n’est publié sans son accord.</span></div></li>\n        <li><div><b>Après la livraison</b><span>Avec l’abonnement, l’équipe garde le site en ligne, sécurisé et à jour, et ajoute ses actualités. Pour une question, il contacte directement l’équipe.</span></div></li>\n      </ol>\n    </section>\n\n    <section id=\"messages\">\n      <h2>Modèles de messages</h2>\n      <p class=\"section-intro\">Remplacez les passages <span class=\"var\">en violet</span> avant d’envoyer. Un message personnalisé, avec une vraie observation sur le commerce, obtient bien plus de réponses qu’un copier-coller.</p>\n\n      <div class=\"template\">\n        <div class=\"template-head\"><b>Premier message (Instagram ou e-mail)</b><button class=\"copy\" type=\"button\" data-copy-from=\"t1\">Copier</button></div>\n        <div class=\"template-body\" id=\"t1\">Bonjour <span class=\"var\">nom du commerce</span>,\n\nJe m’appelle <span class=\"var\">votre prénom</span> et je fais partie d’Astrinova : nous créons des sites internet pour les commerces.\n\nEn regardant <span class=\"var\">votre page Instagram / votre fiche Google</span>, j’ai remarqué que <span class=\"var\">observation précise : pas de site, carte introuvable, pas de réservation en ligne…</span>.\n\nUn site vous permettrait de <span class=\"var\">bénéfice concret : être trouvé sur Google, montrer votre carte, prendre des réservations…</span>\n\nNos prix sont affichés et le site se paie une seule fois, à partir de 290 €. Vous pouvez composer votre site et voir le total vous-même ici : https://getnovaai.vercel.app/tarifs.html\n\nSi ce n’est pas le moment, dites-le-moi simplement et je ne vous relancerai pas.\n\n<span class=\"var\">Votre prénom</span>, Astrinova</div>\n      </div>\n\n      <div class=\"template\">\n        <div class=\"template-head\"><b>Client intéressé : les tarifs et le formulaire</b><button class=\"copy\" type=\"button\" data-copy-from=\"t6\">Copier</button></div>\n        <div class=\"template-body\" id=\"t6\">Merci pour votre intérêt ! Voici les deux liens pour avancer :\n\n– nos tarifs, pour composer votre site et voir le prix exact : https://getnovaai.vercel.app/tarifs.html\n– un court formulaire (environ 4 minutes) pour nous dire vos goûts, afin que la maquette vous ressemble : https://astrinovaformulaire.netlify.app/\n\nL’équipe revient vers vous très vite. Pour toute question : astrinova.website@gmail.com, ou par téléphone au 06 22 82 88 32 ou au 06 52 23 75 73.\n\n<span class=\"var\">Votre prénom</span>, Astrinova</div>\n      </div>\n\n      <div class=\"template\">\n        <div class=\"template-head\"><b>Relance (une seule, quelques jours plus tard)</b><button class=\"copy\" type=\"button\" data-copy-from=\"t2\">Copier</button></div>\n        <div class=\"template-body\" id=\"t2\">Bonjour <span class=\"var\">nom du commerce</span>,\n\nJe me permets de revenir vers vous au sujet de votre site internet. Vous pouvez voir des sites que nous avons réalisés ici : https://getnovaai.vercel.app/deja-en-ligne.html\n\nSi cela ne vous intéresse pas, aucun souci : ce sera mon dernier message.\n\n<span class=\"var\">Votre prénom</span>, Astrinova</div>\n      </div>\n\n      <div class=\"template\">\n        <div class=\"template-head\"><b>Après l’envoi du mail détaillé par l’équipe</b><button class=\"copy\" type=\"button\" data-copy-from=\"t3\">Copier</button></div>\n        <div class=\"template-body\" id=\"t3\">Bonjour, nous venons de vous envoyer un mail avec toutes les informations sur votre futur site. Une question ? Nous répondons ici comme par mail, ou par téléphone au 06 22 82 88 32 ou au 06 52 23 75 73. À très vite, <span class=\"var\">votre prénom</span> (Astrinova)</div>\n      </div>\n\n      <div class=\"template\">\n        <div class=\"template-head\"><b>Réponse à quelqu’un qui a eu une mauvaise expérience</b><button class=\"copy\" type=\"button\" data-copy-from=\"t4\">Copier</button></div>\n        <div class=\"template-body\" id=\"t4\">Bonjour,\n\nMerci d’avoir pris le temps de nous répondre, et nous sommes désolés pour ce qui vous est arrivé. Après une expérience pareille, votre méfiance est tout à fait normale.\n\nNous travaillons justement à l’opposé de ce genre de pratiques :\n– nos prix sont affichés publiquement, et vous pouvez composer votre site vous-même pour voir le total exact, sans laisser vos coordonnées ;\n– le site se paie une seule fois : pas de contrat de location sur plusieurs années ;\n– l’abonnement (hébergement, mises à jour) est facultatif et résiliable à tout moment.\n\nJugez par vous-même ici : https://getnovaai.vercel.app/tarifs.html\nNos réalisations sont aussi visibles sur le site, dans « Déjà en ligne ».\n\nSi vous préférez en parler de vive voix, nous sommes joignables au 06 22 82 88 32 ou au 06 52 23 75 73. Et si vous ne souhaitez plus être contacté, dites-le-nous simplement : nous respecterons votre choix.\n\nBonne journée,\n<span class=\"var\">Votre prénom</span>, Astrinova</div>\n      </div>\n\n      <h3>Trame d’appel téléphonique</h3>\n      <ol class=\"steps\">\n        <li><div><b>Se présenter en une phrase</b><span>« Bonjour, <span class=\"var\">votre prénom</span> d’Astrinova, nous créons des sites internet pour les commerces. Je vous prends deux minutes ? »</span></div></li>\n        <li><div><b>Dire pourquoi vous l’appelez, lui</b><span>Une observation précise : pas de site, horaires introuvables, pas de réservation en ligne…</span></div></li>\n        <li><div><b>Poser une question ouverte</b><span>« Aujourd’hui, comment vos nouveaux clients vous trouvent-ils ? »</span></div></li>\n        <li><div><b>Proposer le lien, pas un engagement</b><span>« Je vous envoie le lien de nos tarifs par SMS ou par e-mail : vous composez votre site et vous voyez le prix tout de suite. »</span></div></li>\n        <li><div><b>Conclure poliment</b><span>S’il n’est pas intéressé, remerciez-le et notez de ne plus le recontacter.</span></div></li>\n      </ol>\n    </section>\n\n    <section id=\"faq\">\n      <h2>Questions fréquentes</h2>\n      <p class=\"section-intro\">Ce que vous pouvez répondre, avec des informations vérifiées. Cliquez sur une question pour voir la réponse.</p>\n      <div class=\"faq-tools\">\n        <label class=\"sr-only\" for=\"faq-search\">Rechercher une question</label>\n        <input id=\"faq-search\" type=\"search\" placeholder=\"Rechercher : prix, contrat, photos, Google…\" autocomplete=\"off\">\n        <span class=\"faq-count\" id=\"faq-count\" aria-live=\"polite\"></span>\n      </div>\n      <div id=\"faq-list\">\n        <details><summary>Combien ça coûte ?</summary><div><p>Le site se paie une seule fois : 290 € (Essentiel), 490 € (Pro) ou 990 € (Signature), plus les options choisies. L’abonnement est en plus, s’il le souhaite : 25 € par mois (15 € avec Signature). Le plus simple : envoyez-lui la page Tarifs, il voit le total exact.</p></div></details>\n        <details><summary>Faut-il signer un contrat ? Y a-t-il un engagement ?</summary><div><p>Pas de contrat sur plusieurs années : le prix est annoncé avant de commencer et le site se paie une seule fois. L’abonnement est facultatif et résiliable à tout moment.</p></div></details>\n        <details><summary>Combien de temps pour avoir mon site ?</summary><div><p>1 semaine maximum pour Essentiel, 2 semaines pour Pro et 1 mois pour Signature.</p></div></details>\n        <details><summary>Est-ce que je verrai le site avant qu’il soit en ligne ?</summary><div><p>Oui. Grâce au formulaire de maquette (environ 4 minutes), l’équipe réalise une maquette à son image et lui envoie des captures. Il voit ensuite le site finalisé et peut demander des ajustements. Rien n’est publié sans son accord.</p></div></details>\n        <details><summary>Je n’ai pas de photos professionnelles ni de textes.</summary><div><p>Ce n’est pas un problème : l’équipe trouve avec lui la meilleure solution à partir de ce qu’il a.</p></div></details>\n        <details><summary>C’est quoi l’abonnement exactement ?</summary><div><p>Nous gardons le site en ligne : hébergement, nom de domaine, sécurité et mises à jour. Nous ajoutons aussi ses actualités pour lui (nouvelle boisson de saison, nouvelles offres…). 25 € par mois avec Essentiel ou Pro, 15 € avec Signature. Facultatif et résiliable à tout moment.</p></div></details>\n        <details><summary>Est-ce que je serai bien visible sur Google ?</summary><div><p>Proposez l’option «&nbsp;Fiche Google optimisée et QR code d’avis&nbsp;» (75 €) : c’est souvent la première chose que voient ses futurs clients. Ne promettez jamais une première place sur Google : personne ne peut la garantir.</p></div></details>\n        <details><summary>Est-ce que mes clients pourront commander ou réserver en ligne ?</summary><div><p>Oui, avec l’option commande en ligne (dès 290 €) ou réservation en ligne (dès 120 €). Avec le pack Signature, l’une des deux est incluse.</p></div></details>\n        <details><summary>J’ai besoin d’une fonctionnalité qui n’est pas dans la liste.</summary><div><p>Il ajoute l’option «&nbsp;Sur mesure&nbsp;» tout en bas de la page Tarifs et décrit ce qu’il veut, même plusieurs choses. L’équipe lui répond avec un prix adapté.</p></div></details>\n        <details><summary>Le site sera-t-il adapté aux téléphones ?</summary><div><p>Oui, tous les sites sont optimisés pour le mobile en priorité, là où la majorité de ses clients le chercheront.</p></div></details>\n        <details><summary>Avez-vous des exemples ?</summary><div><p>Oui : la page «&nbsp;Déjà en ligne&nbsp;» montre nos réalisations classées par pack. Voir la section <a href=\"#realisations\">Réalisations</a> de ce guide.</p></div></details>\n        <details><summary>Comment vous contacter ?</summary><div><p>Par la page Contact du site, par e-mail (astrinova.website@gmail.com) ou par téléphone (06 22 82 88 32 ou 06 52 23 75 73). Réponse sous 24 h.</p></div></details>\n        <details><summary>À quoi sert le formulaire de maquette ?</summary><div><p>À connaître ses goûts (ambiance, style, couleurs, logo, ce qu’il ne veut pas, sites qui l’inspirent, pages voulues) pour que la maquette lui ressemble. 8 questions, environ 4 minutes, tout est facultatif sauf le nom du commerce et un moyen de le joindre. Les réponses nous arrivent automatiquement.</p></div></details>\n        <details><summary>Que deviennent mes informations si j’envoie une demande ?</summary><div><p>Elles servent uniquement à lui répondre et à préparer son devis. Tout est expliqué sur la page <a href=\"https://getnovaai.vercel.app/confidentialite.html\" target=\"_blank\" rel=\"noopener\">Confidentialité</a>.</p></div></details>\n      </div>\n      <p class=\"faq-count\" id=\"faq-vide\" hidden>Aucune question ne correspond. Essayez un autre mot, ou renvoyez la question vers l’équipe.</p>\n\n      <h3>Les questions à renvoyer vers l’équipe</h3>\n      <p>Sur ces sujets, ne répondez pas à la place de l’équipe et ne promettez rien. Dites simplement : « Je transmets votre question à l’équipe, qui vous répond sous 24 h. »</p>\n      <ul class=\"plain\">\n        <li>Les modalités de paiement (acompte, paiement en plusieurs fois, moment du paiement).</li>\n        <li>Ce qui se passe pour le site sans abonnement, ou après une résiliation.</li>\n        <li>La propriété du site et des fichiers une fois livré.</li>\n        <li>Le nombre de retouches compris dans le prix.</li>\n        <li>Toute remise, tout prix spécial ou tout délai plus court que ceux annoncés.</li>\n        <li>La reprise d’un site existant.</li>\n        <li>Les factures et les informations administratives de l’entreprise.</li>\n      </ul>\n    </section>\n\n    <section id=\"objections\">\n      <h2>Répondre aux objections</h2>\n      <p class=\"section-intro\">Écoutez d’abord, répondez ensuite avec un fait, puis laissez le choix.</p>\n      <div class=\"table-wrap\">\n        <table>\n          <thead><tr><th>Ce qu’il dit</th><th>Ce que vous pouvez répondre</th></tr></thead>\n          <tbody>\n            <tr><td>« C’est trop cher. »</td><td>Le site se paie une seule fois, à partir de 290 € avec Essentiel. Il peut ne prendre que les options vraiment utiles et voir le total exact sur la page Tarifs.</td></tr>\n            <tr><td>« J’ai déjà Instagram / Facebook. »</td><td>Un site complète ses réseaux : on le trouve sur Google et il réunit tout au même endroit (carte, horaires, adresse, contact). L’option «&nbsp;Fil Instagram intégré&nbsp;» affiche même ses publications sur le site.</td></tr>\n            <tr><td>« Je n’ai pas le temps. »</td><td>Il n’a rien de technique à faire : un formulaire d’environ 4 minutes sur ses goûts, puis il valide la maquette. Avec l’abonnement, nous ajoutons ses actualités pour lui.</td></tr>\n            <tr><td>« J’ai déjà un site. »</td><td>Demandez ce qui lui manque (commande, réservation, mobile, Google…). Pour une refonte, transmettez à l’équipe.</td></tr>\n            <tr><td>« J’ai déjà été arnaqué / je suis en procès. »</td><td>Ne discutez pas de son affaire et ne critiquez pas l’autre entreprise. Montrez la différence : prix publics, paiement unique, pas de location, abonnement résiliable. Utilisez le modèle «&nbsp;mauvaise expérience&nbsp;» de ce guide.</td></tr>\n            <tr><td>« Je vais réfléchir. »</td><td>Laissez-lui le lien de la page Tarifs pour composer son site quand il veut. Une seule relance, quelques jours plus tard.</td></tr>\n            <tr><td>« Ça ne m’intéresse pas. »</td><td>Remerciez-le, et ne le recontactez plus.</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </section>\n\n    <section id=\"regles\">\n      <h2>Les règles d’or</h2>\n      <p class=\"section-intro\">La confiance est notre meilleur argument. Ces règles la protègent, et vous protègent aussi.</p>\n      <div class=\"rules\">\n        <div class=\"rule-col do\">\n          <h3>À faire</h3>\n          <ul>\n            <li>Vouvoyer, rester simple, sans jargon technique.</li>\n            <li>Personnaliser chaque message avec une vraie observation sur le commerce.</li>\n            <li>Envoyer le lien de la page Tarifs : le prix parle de lui-même.</li>\n            <li>Toujours laisser un moyen simple de refuser (« dites-le-moi simplement »).</li>\n            <li>Ne contacter les commerces que pour leur activité professionnelle.</li>\n            <li>Prévenir l’équipe dès qu’un client est intéressé, et lui envoyer les tarifs et le formulaire.</li>\n            <li>Renvoyer vers l’équipe (astrinova.website@gmail.com) dès que vous n’êtes pas sûr d’une réponse.</li>\n          </ul>\n        </div>\n        <div class=\"rule-col dont\">\n          <h3>À ne jamais faire</h3>\n          <ul>\n            <li>Promettre un prix, un délai ou une condition qui n’est pas sur le site.</li>\n            <li>Garantir une première place sur Google ou un nombre de clients.</li>\n            <li>Inventer des avis, des témoignages, des chiffres ou une fausse urgence (« plus que 2 places »).</li>\n            <li>Relancer plus d’une fois, ou recontacter quelqu’un qui a dit non.</li>\n            <li>Encaisser un paiement ou demander des coordonnées bancaires : le devis et le paiement passent par l’équipe.</li>\n            <li>Partager les coordonnées des prospects en dehors de l’équipe.</li>\n            <li>Dénigrer un concurrent.</li>\n          </ul>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"transmettre\">\n      <h2>Transmettre un prospect intéressé</h2>\n      <p class=\"section-intro\">À faire dès qu’un commerçant montre de l’intérêt, même s’il hésite encore.</p>\n      <h3>1. Prévenez l’équipe</h3>\n      <p>Envoyez un e-mail à <strong>astrinova.website@gmail.com</strong> avec cette fiche&nbsp;:</p>\n      <div class=\"template\">\n        <div class=\"template-head\"><b>Fiche de transmission</b><button class=\"copy\" type=\"button\" data-copy-from=\"t5\">Copier</button></div>\n        <div class=\"template-body\" id=\"t5\">Objet : Prospect intéressé — <span class=\"var\">nom du commerce</span>\n\nCommerce : <span class=\"var\">nom et type de commerce</span>\nVille : <span class=\"var\">ville</span>\nContact : <span class=\"var\">nom, téléphone, e-mail</span>\nMeilleur moment pour l’appeler : <span class=\"var\">jour, heure</span>\nCe qu’il veut : <span class=\"var\">pack envisagé, options, abonnement oui / non</span>\nSes questions ou hésitations : <span class=\"var\">…</span>\nComment je l’ai contacté : <span class=\"var\">Instagram / e-mail / téléphone / en boutique</span>\nTarifs et formulaire envoyés : <span class=\"var\">oui / pas encore</span>\n<span class=\"var\">Votre prénom</span></div>\n      </div>\n      <h3>2. Envoyez-lui les tarifs et le formulaire</h3>\n      <p>Utilisez le modèle «&nbsp;<a href=\"#messages\">Client intéressé</a>&nbsp;» : il contient le lien de la page Tarifs et celui du formulaire de maquette. S’il compose son site et clique sur «&nbsp;Envoyer ma demande&nbsp;», sa demande nous arrive avec tout le détail de son panier.</p>\n    </section>\n\n    <section id=\"lexique\">\n      <h2>Lexique</h2>\n      <p class=\"section-intro\">Pour expliquer les termes techniques avec des mots simples.</p>\n      <dl class=\"glossary\">\n        <div><dt>Nom de domaine</dt><dd>L’adresse du site, comme moncommerce.fr. Compris dans l’abonnement.</dd></div>\n        <div><dt>Hébergement</dt><dd>Le service qui garde le site en ligne, jour et nuit. Compris dans l’abonnement.</dd></div>\n        <div><dt>Maquette</dt><dd>Une première version du site, montrée au client avant la mise en ligne.</dd></div>\n        <div><dt>Click &amp; collect</dt><dd>Le client commande et paie en ligne, puis vient chercher sa commande en boutique.</dd></div>\n        <div><dt>Fiche Google</dt><dd>La fiche du commerce dans Google Maps : adresse, horaires, photos, avis.</dd></div>\n        <div><dt>QR code</dt><dd>Un carré à scanner avec le téléphone, qui ouvre directement une page (la carte, la page d’avis…).</dd></div>\n        <div><dt>Optimisé mobile</dt><dd>Le site s’affiche parfaitement sur téléphone.</dd></div>\n        <div><dt>« À partir de »</dt><dd>Prix de départ d’une option : le prix exact est confirmé par l’équipe dans le devis.</dd></div>\n        <div><dt>Sur devis</dt><dd>Le prix est calculé après avoir lu la demande du client.</dd></div>\n        <div><dt>Devis</dt><dd>Le document qui détaille ce qui sera fait et le prix, envoyé par l’équipe avant de commencer.</dd></div>\n      </dl>\n    </section>\n\n    <footer class=\"end\">\n      <p>Guide interne Astrinova. Les prix et le contenu des packs reprennent la page Tarifs au 13 octobre 2026 ; ils peuvent évoluer, et c’est toujours la page en ligne qui fait foi.</p>\n    </footer>\n  </main>\n</div>\n\n<script>\n(function () {\n  'use strict';\n\n  // Boutons « Copier » : lien direct (data-copy) ou texte d'un modèle (data-copy-from).\n  function copier(texte, bouton) {\n    var fini = function (ok) {\n      bouton.textContent = ok ? 'Copié' : 'Texte sélectionné';\n      bouton.classList.toggle('done', ok);\n      setTimeout(function () { bouton.textContent = 'Copier'; bouton.classList.remove('done'); }, 1800);\n    };\n    var selectionner = function () {\n      var id = bouton.getAttribute('data-copy-from');\n      var cible = id ? document.getElementById(id) : bouton.parentNode.querySelector('a, code');\n      if (!cible) return fini(false);\n      var plage = document.createRange();\n      plage.selectNodeContents(cible);\n      var sel = window.getSelection();\n      sel.removeAllRanges();\n      sel.addRange(plage);\n      fini(false);\n    };\n    try {\n      if (navigator.clipboard && navigator.clipboard.writeText) {\n        navigator.clipboard.writeText(texte).then(function () { fini(true); }, selectionner);\n      } else { selectionner(); }\n    } catch (e) { selectionner(); }\n  }\n  document.addEventListener('click', function (e) {\n    var b = e.target.closest('button.copy');\n    if (!b) return;\n    var source = b.getAttribute('data-copy-from');\n    var texte = source ? document.getElementById(source).innerText.trim() : b.getAttribute('data-copy');\n    copier(texte, b);\n  });\n\n  // Recherche dans les questions fréquentes (sans tenir compte des accents).\n  var champ = document.getElementById('faq-search');\n  var items = Array.prototype.slice.call(document.querySelectorAll('#faq-list details'));\n  var compte = document.getElementById('faq-count');\n  var vide = document.getElementById('faq-vide');\n  function normaliser(s) { return s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, ''); }\n  champ.addEventListener('input', function () {\n    var q = normaliser(champ.value.trim());\n    var visibles = 0;\n    items.forEach(function (d) {\n      var ok = !q || normaliser(d.textContent).indexOf(q) !== -1;\n      d.hidden = !ok;\n      if (ok) visibles++;\n      if (q && ok) d.open = true;\n    });\n    compte.textContent = q ? visibles + ' question' + (visibles > 1 ? 's' : '') : '';\n    vide.hidden = visibles > 0;\n  });\n\n  // Sommaire : la section affichée est mise en avant.\n  var liens = Array.prototype.slice.call(document.querySelectorAll('.toc a'));\n  if ('IntersectionObserver' in window) {\n    var obs = new IntersectionObserver(function (entries) {\n      entries.forEach(function (en) {\n        if (!en.isIntersecting) return;\n        liens.forEach(function (a) { a.classList.toggle('is-here', a.getAttribute('href') === '#' + en.target.id); });\n      });\n    }, { rootMargin: '-20% 0px -70% 0px' });\n    Array.prototype.forEach.call(document.querySelectorAll('main section[id]'), function (s) { obs.observe(s); });\n  }\n})();\n</script>\n\n</body></html>";
